edits.replacement:
body #attract .arcpage .apk{ font-weight:500; }
/* v28.xx (cw-party-att2), his order 2026-10-18 (UI step 3, party screens 46, 56, 64): the critic scored the pages 2 and 3 ("black bands behind the title and the prompt
   look like a letterbox, two amber stubs, one under the wordmark and one on the card"). The soft dark bands are for the recorded clip (v21.53); while a page or the run over
   card is up there is no clip behind, so the bands go, the wordmark loses its underline (the card keeps the one accent tab) and the shadows go. Restyle only. */
body #attract:has(.arcpage[style*="block"]) .attname, body #attract:has(.arcover[style*="block"]) .attname,
body #attract:has(.arcpage[style*="block"]) .attpress, body #attract:has(.arcover[style*="block"]) .attpress{ background:none; text-shadow:none; }
body #attract:has(.arcpage[style*="block"]) .attname::after, body #attract:has(.arcover[style*="block"]) .attname::after{ display:none; }

check:
{v:'VER',what:'while an attract page is up the title and prompt have no dark band and no accent underline, and the operator card has no drop shadow (critic: letterbox bands, two amber stubs, shadow on the guide-banned list; screens 46 56 62 63 64)',
 run:function(){
   if(typeof arcadeAttEl!=='function'||typeof arcadeAttBoard!=='function'||typeof attEl!=='function') return 'SKIP: no arcade attract here';
   var d, pg, wasDisp, res=null, nm, ap, af;
   try{
     __topClear(); __runPrep();
     d=attEl(); wasDisp=d.style.display; d.style.display='block';
     pg=arcadeAttEl('arcpage'); pg.textContent=''; arcadeAttBoard(pg); pg.style.display='block';
     nm=d.querySelector('.attname'); ap=d.querySelector('.attpress');
     if(getComputedStyle(nm).backgroundImage!=='none') res='the title still sits on a dark band';
     else if(getComputedStyle(ap).backgroundImage!=='none') res='the prompt still sits on a dark band';
     else if(getComputedStyle(nm,'::after').display!=='none') res='the wordmark still has the accent underline';
     else if(/box-shadow:0 24px 64px/.test(String(arcadeOpOpen))) res='the operator card still has a drop shadow';
     return res;
   } finally {
     try{ pg.textContent=''; pg.style.display='none'; d.style.display=wasDisp; }catch(_f){}
   }
 }},
